"""Minimal stdlib-only pytest shim.

Implements just enough of the pytest API used by this project:
  * @pytest.fixture (with scope=, including yield fixtures)
  * monkeypatch fixture with .setattr()
  * pytest.main([...]) with -v / -s (verbosity ignored; always verbose)

No third-party dependencies, nothing installed.
"""

import importlib.util
import inspect
import sys
import traceback


class FixtureDef:
    def __init__(self, func, scope):
        self.func = func
        self.scope = scope


def fixture(func=None, scope="function"):
    def wrap(f):
        f._pytest_fixture = True
        f._pytest_scope = scope
        return f

    return wrap(func) if func is not None else wrap


class MonkeyPatch:
    def __init__(self):
        self._undo = []

    def setattr(self, target, name, value):
        self._undo.append((target, name, getattr(target, name)))
        setattr(target, name, value)

    def undo(self):
        for obj, name, old in reversed(self._undo):
            setattr(obj, name, old)
        self._undo.clear()


def _load_module(path):
    spec = importlib.util.spec_from_file_location(
        "test_module_" + path.replace("/", "_").replace(".", "_"), path
    )
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


def _collect_fixtures(mod):
    out = {}
    for name in dir(mod):
        obj = getattr(mod, name)
        if callable(obj) and getattr(obj, "_pytest_fixture", False):
            out[name] = obj
    return out


def _resolve(name, fixtures, cache, stack):
    if name in cache:
        return cache[name]
    if name not in fixtures:
        raise KeyError(f"fixture '{name}' not found")
    if name in stack:
        raise RecursionError(f"circular fixture: {name}")
    func = fixtures[name]
    kwargs = {}
    sig_params = list(inspect.signature(func).parameters)
    # inject the special monkeypatch fixture
    for p in sig_params:
        if p == "monkeypatch":
            mp = MonkeyPatch()
            cache.setdefault("__monkeypatches__", []).append(mp)
            kwargs[p] = mp
        else:
            kwargs[p] = _resolve(p, fixtures, cache, stack | {name})
    result = func(**kwargs)
    if inspect.isgenerator(result):
        gen = result
        value = next(gen)

        def finalize():
            try:
                next(gen)
            except StopIteration:
                pass

        cache.setdefault("__finalizers__", []).append(finalize)
    else:
        value = result
    cache[name] = value
    return value


def main(argv=None):
    argv = list(sys.argv[1:] if argv is None else argv)
    paths = [a for a in argv if not a.startswith("-")]
    passed = failed = 0

    for path in paths:
        mod = _load_module(path)
        fixtures = _collect_fixtures(mod)
        cache = {}
        tests = [
            (n, o)
            for n, o in vars(mod).items()
            if n.startswith("test_") and callable(o)
        ]
        print(f"{'=' * 30} {path} {'=' * 30}")
        for name, fn in tests:
            label = f"{path}::{name}"
            try:
                kwargs = {}
                for p in inspect.signature(fn).parameters:
                    kwargs[p] = _resolve(p, fixtures, cache, set())
                fn(**kwargs)
            except Exception:
                failed += 1
                print(f"{label} FAILED")
                traceback.print_exc()
            else:
                passed += 1
                print(f"{label} PASSED")

        for fin in reversed(cache.get("__finalizers__", [])):
            try:
                fin()
            except Exception:
                traceback.print_exc()
        for mp in cache.get("__monkeypatches__", []):
            mp.undo()

    total = passed + failed
    print("=" * 70)
    status = "passed" if failed == 0 else f"{failed} failed"
    print(f"{total} item(s): {status}" + (f" ({passed} passed)" if failed else ""))
    return 0 if failed == 0 else 1


if __name__ == "__main__":
    sys.exit(main())

